import {readFileSync} from 'node:fs';
const parse = p => {
  const s = readFileSync(p, 'utf8');
  const m = {};
  for (const b of s.split('end_of_record')) {
    const f = (/SF:(.*)/.exec(b) || [])[1];
    if (!f) continue;
    const da = [...b.matchAll(/^DA:(\d+),(\d+)$/gm)].map(x => [Number(x[1]), Number(x[2])]);
    m[f] = da;
  }
  return m;
};
const a = parse(process.argv[2]);
const b = parse(process.argv[3]);
for (const f of Object.keys(b)) {
  if (!a[f]) {
    console.log('NEW', f);
    continue;
  }
  const hitA = new Map(a[f]);
  const lost = b[f].filter(([ln, hit]) => hit > 0 && !(hitA.get(ln) > 0));
  if (lost.length) console.log('LOST-HITS', f, JSON.stringify(lost.slice(0, 20)));
}

