import {readFileSync, readdirSync, statSync} from 'node:fs';
import {join, relative, sep} from 'node:path';

const root = process.argv[2] ?? process.cwd();

// Walk specs/ and adrs/ for citations.
const corpus = [];
const walk = dir => {
  for (const entry of readdirSync(dir)) {
    const p = join(dir, entry);
    if (statSync(p).isDirectory()) {
      if (entry === 'node_modules' || entry === 'fixtures' || entry === '.git') continue;
      walk(p);
    } else if (p.endsWith('.md')) {
      const src = readFileSync(p, 'utf8');
      for (const m of src.matchAll(/\[validated by(?:: ([^\]]*))?\]\(\.\.\/((?:[^)#\s]+))#L(\d+)\)/g)) {
        corpus.push({spec: relative(root, p), name: m[1] ?? null, path: m[2], line: Number(m[3])});
      }
    }
  }
};
walk(join(root, 'specs'));
walk(join(root, 'adrs'));

// Resolve citation paths (spec-relative with ../ prefixes) to repo paths.
const cited = new Set(); // `${repoPath}::${name}`
const byFile = new Map(); // repoPath -> array of lines
for (const c of corpus) {
  const repoPath = relative(root, join(c.spec, '..', c.path)).split(sep).join('/');
  cited.add(`${repoPath}::${c.name}`);
  if (!byFile.has(repoPath)) byFile.set(repoPath, []);
  byFile.get(repoPath).push(c.line);
